{
  "contract": "Yeeter",
  "closure": {
    "site_function": "yeetyeet",
    "site_call": ".call",
    "functions": [
      "<fallback>",
      "yeetyeet"
    ],
    "justification": "Includes all functions that can be called during the callback window and affect exposed storage."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "<fallback>"
    ],
    "nesting_bound": {
      "yeetyeet": 1
    }
  },
  "phases": {
    "function": "yeetyeet",
    "pre": {
      "name": "pre",
      "from_marker": "require(_status == _NOT_ENTERED)",
      "to_marker": "_status = _ENTERED"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "_status = _ENTERED",
      "to_marker": "_status = _NOT_ENTERED"
    },
    "post": {
      "name": "post",
      "from_marker": "_status = _NOT_ENTERED",
      "to_marker": "return"
    },
    "linearization_point": "_status = _NOT_ENTERED"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of deposits in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_deposits == balance + inFlight",
    "stable_formula": "_sum_deposits == balance",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_deposits == balance",
    "rule": "The exposure invariant ensures that the sum of deposits is conserved across the callback window, accounting for in-flight changes."
  }
}
